 function realEstateForm(){const cur=asset();const body='<div class="u-real-estate-callout"><strong>Earnest-only sandbox</strong><p>Use a fictional property reference. This prototype records an earnest-money deposit and closing checklist; it does not hold funds, verify title, provide legal advice, or act as a settlement agent.</p></div>'+selectField('Buyer / seller counterparty','sellerId',selectors(s().users.filter(u=>u.role==='seller'&&u.id!==me().id&&!blocked(u.id)).map(u=>[u.id,u.name+' · demo seller'])))+field('Agreement title','title','text','Purchase deposit agreement','','required minlength="8" maxlength="120"')+selectField('Transaction type','transactionType',selectors([['residential_purchase','Residential purchase'],['commercial_purchase','Commercial purchase'],['land_purchase','Land purchase']]))+field('Fictional property reference','propertyReference','text','','Example: Project Atlas · Unit B12. Do not enter a street address or postal code.','required minlength="4" maxlength="160"')+field('Purchase price (demo '+e(cur)+')','purchasePrice','text','25000','','required inputmode="decimal"')+field('Earnest deposit (demo '+e(cur)+')','earnestDeposit','text','5000','Only the earnest deposit is simulated in this sandbox.','required inputmode="decimal"')+field('Deal notes and scope','scope','textarea','','Describe the deposit purpose and agreed transaction scope. Do not include personal data.','required minlength="20" maxlength="4000"')+'<div class="form-grid">'+field('Inspection / due-diligence days','inspectionDays','number','10','','required min="1" max="30"')+field('Target closing date','targetClosingDate','date','','Must be within the next year.','required')+selectField('Settlement contact label','settlementContact',selectors([['Demo title company','Demo title company'],['Demo closing attorney','Demo closing attorney'],['Demo settlement agent','Demo settlement agent']]))+'</div><div class="u-contingency-grid"><label class="checkbox-label"><input name="financingContingency" type="checkbox" checked><span>Financing contingency applies</span></label><label class="checkbox-label"><input name="appraisalContingency" type="checkbox" checked><span>Appraisal contingency applies</span></label></div>'+field('Closing conditions (one per line)','closingConditions','textarea','Inspection / due-diligence review completed or waived\nFinancing and appraisal conditions resolved or documented\nTitle / settlement review completed by the qualified professionals\nParties confirm the closing statement and disbursement instructions through known contacts','These become the agreement checklist.','required minlength="30" maxlength="4000"')+feePolicy()+'<label class="checkbox-label"><input name="agreeRealEstate" type="checkbox" required> I understand this is a demo workflow, not a title company, escrow agent, attorney, lender, or payment custodian.</label><label class="checkbox-label"><input name="agreeWireSafety" type="checkbox" required> I will verify any payment instructions using a known phone number or trusted contact and will not rely on last-minute wiring changes.</label>';b.modal('u:agreement','Create a real-estate escrow plan.',body,'Create real-estate agreement',{workflow:'real_estate',asset:cur});}
