  async function submitModal(form,c,operationKey){const v=Object.fromEntries(new FormData(form));let result,target;const kind=c.kind.slice(2),base={orderId:c.orderId,expectedVersion:c.expectedVersion};if(kind==='purchase'){result=await b.command('purchase_product',{listingId:c.listingId,quantity:Number(v.quantity),requirements:v.requirements,deliveryReference:v.deliveryReference,agreeInspection:v.agreeInspection==='on',agreeFees:v.agreeFees==='on',asset:c.asset},operationKey);target='#/deal/'+result;}
  else if(kind==='domain'){const askingPrices={},minimumOffers={};if(v.askingUSDC)askingPrices.USDC=v.askingUSDC;if(v.askingUSDT)askingPrices.USDT=v.askingUSDT;if(v.minimumUSDC)minimumOffers.USDC=v.minimumUSDC;if(v.minimumUSDT)minimumOffers.USDT=v.minimumUSDT;await b.command('create_domain',{domainName:v.domainName,title:v.title,description:v.description,registrar:v.registrar,expiryDate:v.expiryDate,transferMethod:v.transferMethod,renewalResponsibility:v.renewalResponsibility,includedAssets:lines(v.includedAssets),askingPrices,minimumOffers,ownershipConfirmed:v.ownershipConfirmed==='on',controlChallenge:v.controlChallenge},operationKey);target='#/studio';}
  else if(kind==='domain-purchase'){result=await b.command('purchase_domain',{listingId:c.listingId,asset:c.asset,requirements:v.requirements,agreeTerms:v.agreeTerms==='on',offerId:c.offerId||''},operationKey);target='#/deal/'+result;}
  else if(kind==='domain-offer'){await b.command('make_domain_offer',{listingId:c.listingId,asset:c.asset,amount:v.amount},operationKey);target='#/domain/'+c.listingId;}
  else if(kind==='domain-offer-response'){await b.command('respond_domain_offer',{offerId:c.offerId,decision:c.decision,amount:v.amount},operationKey);target='#/domain/'+c.listingId;}
  else if(kind==='domain-verify'){await b.command('verify_domain_control',{listingId:c.listingId,proof:v.proof,note:v.note},operationKey);target='#/domain/'+c.listingId;}
  else if(kind==='domain-transfer-initiate'){await b.command('initiate_domain_transfer',{orderId:c.orderId,expectedVersion:c.expectedVersion,transferReference:v.transferReference},operationKey);}
  else if(kind==='domain-transfer-verify'){await b.command('verify_domain_transfer',{orderId:c.orderId,expectedVersion:c.expectedVersion,dnsProof:v.dnsProof},operationKey);}
  else if(kind==='domain-transfer-reject'){await b.command('reject_domain_transfer',{orderId:c.orderId,expectedVersion:c.expectedVersion,reason:v.reason,acknowledgeFee:v.acknowledgeFee==='on'},operationKey);}
  else if(kind==='product'){const {holdback,criteria,price,priceUSDT,shipping,shippingUSDT,...rest}=v;for(const k of ['stock','days','inspectionDays','warrantyDays'])rest[k]=Number(rest[k]);const prices={},shippingPrices={};if(price!==''&&price!==undefined)prices.USDC=price;if(priceUSDT!==''&&priceUSDT!==undefined)prices.USDT=priceUSDT;if(!Object.keys(prices).length)throw new Error('Provide at least one price in USDC or USDT.');if(prices.USDC!==undefined)shippingPrices.USDC=(shipping===''||shipping===undefined)?'0':shipping;if(prices.USDT!==undefined)shippingPrices.USDT=(shippingUSDT===''||shippingUSDT===undefined)?'0':shippingUSDT;await b.command('create_product',{...rest,prices,shippingPrices,holdbackBps:Number(holdback)*100,criteria:lines(criteria)},operationKey);target='#/studio';}
  else if(kind==='agreement'){if(c.workflow==='real_estate'){const conditions=lines(v.closingConditions);result=await b.command('create_agreement',{sellerId:v.sellerId,title:v.title,amount:v.earnestDeposit,scope:v.scope,criteria:conditions,requirements:'Buyer and seller will complete the recorded inspection, contingency, title and closing checklist before release.',days:Number(v.inspectionDays),revisions:0,acceptance:'manual',workflow:c.workflow,asset:c.asset,realEstate:{propertyReference:v.propertyReference,transactionType:v.transactionType,purchasePrice:v.purchasePrice,earnestDeposit:v.earnestDeposit,inspectionDays:Number(v.inspectionDays),financingContingency:v.financingContingency==='on',appraisalContingency:v.appraisalContingency==='on',settlementContact:v.settlementContact,targetClosingDate:v.targetClosingDate,closingConditions:conditions}},operationKey);}else result=await b.command('create_agreement',{sellerId:v.sellerId,title:v.title,amount:v.amount,scope:v.scope,criteria:lines(v.criteria),requirements:v.requirements,days:Number(v.days),revisions:Number(v.revisions),acceptance:'manual',workflow:c.workflow,asset:c.asset,milestoneSpecs:[1,2].map(n=>({title:v['title'+n],amount:v['amount'+n],days:Number(v['days'+n]),scope:v['scope'+n],criteria:lines(v['criteria'+n]),role:'delivery'}))},operationKey);target='#/deal/'+result;}
  else if(kind==='report')await b.command('report_listing',{listingId:c.listingId,reason:v.reason},operationKey);
  else if(kind==='moderate-report')await b.command('moderate_listing',{listingId:c.listingId,reportId:c.reportId,decision:v.decision,reason:v.reason},operationKey);
  else if(kind==='evidence'){const file=form.elements.file.files[0];if(!file||file.size>25000000)throw new Error('Choose a file no larger than 25 MB.');if(!crypto.subtle)throw new Error('File hashing needs a secure context. Use the local HTTP server.');const digest=[...new Uint8Array(await crypto.subtle.digest('SHA-256',await file.arrayBuffer()))].map(n=>n.toString(16).padStart(2,'0')).join('');await b.command('add_evidence',{...base,name:file.name,sha256:digest,size:file.size,note:v.note},operationKey);}
 else if(kind==='wallet'){connection=await connectWallet(Number(v.wallet));b.closeModal();b.render();b.toast('External wallet connected. Demo identity and balances are unchanged.');return;}
  else {for(const k of ['acknowledge'])if(k in v)v[k]=v[k]==='on';await b.command(kind,{...base,...v},operationKey);}
 b.closeModal();if(target)b.navigate(target);b.render();b.toast(kind==='report'?'Report recorded for review.':'Saved in the local sandbox.');}
 function connectDialog(){if(window.PACT_NATIVE)throw new Error('Native wallet integration is not enabled in this template.');const ws=availableWallets();if(!ws.length)throw new Error('No Wallet Standard wallet detected. Open this site in a supported wallet browser or install a compatible browser wallet. Never paste a seed phrase.');b.modal('u:wallet','Connect an external wallet.',selectField('Detected wallet','wallet',selectors(ws.map((w,i)=>[String(i),w.name])))+box('A connection, not account authentication','This connection is used only for a signed ownership proof before an on-ramp checkout. It cannot change a demo escrow’s recipients.','warning'),'Connect wallet');}
